public class Main{
  static int[] key=new int[1000], L=new int[1000], R=new int[1000]; static int cnt=0;
  public static void main(String[] a){
    Scanner s=new Scanner(System.in); int n=s.nextInt();
    for(int i=0;i<n;i++){ int x=s.nextInt(); key[cnt]=x; L[cnt]=R[cnt]=-1;
      if(cnt>0){ int c=0; while(true){ if(x<key[c]){ if(L[c]<0){L[c]=cnt;break;} c=L[c]; } else { if(R[c]<0){R[c]=cnt;break;} c=R[c]; } } }
      cnt++; }
    int k=s.nextInt(), c=0, d=0;
    while(c>=0 && cnt>0){ if(key[c]==k){ System.out.println("FOUND "+d); return; } c = k<key[c]?L[c]:R[c]; d++; }
    System.out.println("NOT FOUND");
  }
}

